import { FormEvent, useEffect, useMemo, useState } from "react"

type Product = {
  id: number; name: string; category: string; price: number; old: number; rating: number; reviews: number; image: string; badge?: string
}
type Page = "home"|"shop"|"product"|"wishlist"|"cart"|"checkout"|"success"|"tracking"|"account"|"support"|"review"|"auth"
type Toast = { message: string; type: "success"|"error"|"info" }
type Direction = "A"|"B"|"C"

